# %% [markdown]
# # EXP-004 — zero-GPU re-grade: does the missing inline_snapshot/dirty_equals shim explain the
# # EXP-003-vs-E0 dev-48 gap?
#
# Re-runs grading (not the agent) on the already-submitted patches from two completed dev-48 runs
# (E0 baseline, EXP-003 public-budget-shape test), this time with the two test-only compat shims
# (`tools/compat_shims/*`) dropped into `/workspace` before pytest, gated per task on whether that
# task's own extracted test files import them. This isolates how much of the measured 18.75% vs
# 22.9% resolved-rate gap is a real fix-quality difference vs. a grading-sandbox artifact: a patch
# whose logic was correct but that never reached (or had stripped) its own vendored shim before
# submission (see submission/prompts/swe_coder.md "Known sandbox gaps").
#
# No model, no agent loop, no GPU: `_run_agent_sandbox` is overridden to hand back the already-
# collected patch text directly (see `tools/regrade_patches.py`). Uses `sandbox='subprocess'`, the
# same mode the project's real Kaggle notebooks use (not the real-docker mode `tools/gold_control.py`
# uses, which cannot run on Kaggle).
#
# **Attach as inputs** (Add Input): competition `gemma-4-developer-agent`, dataset
# `metric/gemma-4-developer-agent-wheelhouse`. **No model needed. Accelerator: None (CPU). Internet: off.**
#
# Download `/kaggle/working/runs/EXP-004-regrade-shim.zip`, then compare `regrade_e0.jsonl` /
# `regrade_exp003.jsonl` against the original runs' `task_results.jsonl` locally.

# %%
# ---------------------------------------------------------------- parameters (edit me)
EXP_ID = "EXP-004-regrade-shim"

# Both dev-48 runs graded the same 48-task cohort (confirmed: identical instance_id sets).
TASK_IDS = [
    "fastapi_15661", "fastapi_15589", "fastapi_15030", "fastapi_14962", "fastapi_15280",
    "fastapi_14964", "requests_7427", "requests_7315", "requests_7309", "requests_7205",
    "rich_4070", "rich_4075", "fastapi_14873", "fastapi_14463", "fastapi_14609",
    "fastapi_14512", "fastapi_11355", "fastapi_14459", "fastapi_14448", "fastapi_9753",
    "fastapi_13207", "fastapi_14360", "fastapi_5624", "fastapi_14301", "fastapi_14262",
    "rich_3934", "rich_3953", "rich_3935", "rich_3905", "httpx_3672", "fastapi_15800",
    "fastapi_14605", "fastapi_14583", "fastapi_14297", "fastapi_13537", "fastapi_14953",
    "fastapi_13786", "requests_6644", "rich_3180", "rich_3468", "rich_3676", "rich_3521",
    "rich_3480", "rich_3105", "rich_3067", "rich_3006", "rich_3063", "rich_3061",
]

# Embedded payloads: filled in by the build script (see notebooks/regrade_shim_dev48/README or the
# commit that generated this file), never fetched from the network.
REGRADE_SCRIPT_B64 = ""     # tools/regrade_patches.py source
SHIM_INLINE_B64 = ""        # tools/compat_shims/inline_snapshot/__init__.py source
SHIM_DIRTY_B64 = ""         # tools/compat_shims/dirty_equals/__init__.py source
E0_PATCHES_ZIP_B64 = ""     # zip of runs/E0-dev48-baseline/.../patches/*.patch
EXP003_PATCHES_ZIP_B64 = "" # zip of runs/exp003_public_budget_dev48/.../patches/*.patch

# %%
# ---------------------------------------------------------------- environment + wheelhouse (hosts' recipe)
# Same install recipe as notebooks/kaggle_eval_l4x4.py cell-2, trimmed to the packages this regrade
# actually imports (swegemma, adk_submission for ModelRegistry, adk_eval_core) -- no vLLM/litellm/
# torch/google.adk anywhere in this notebook, so it never touches the GPU.
import glob, importlib, json, io, os, shutil, subprocess, sys, time, zipfile, base64
from pathlib import Path

WHEELHOUSE_DIR = next(Path(p) for p in ['/kaggle/input/datasets/metric/gemma-4-developer-agent-wheelhouse',
                                        '/kaggle/input/gemma-4-developer-agent-wheelhouse'] if Path(p).exists())
for pat in ('/usr/local/lib/python*/dist-packages/*cutlass*.pth', '/usr/local/lib/python*/site-packages/*cutlass*.pth'):
    for pth in glob.glob(pat):
        try:
            os.unlink(pth)
        except OSError:
            pass
tmp_whl = Path('/tmp/wheelhouse'); tmp_whl.mkdir(parents=True, exist_ok=True)
for w in WHEELHOUSE_DIR.glob('*.whl'):
    if 'cutlass' in w.name.lower():
        continue
    name = w.name.replace('cu128', '+cu128') if ('cu128' in w.name and '+' not in w.name) else w.name
    if not (tmp_whl / name).exists():
        os.symlink(w, tmp_whl / name)
REQUIRED_PKGS = ('swegemma', 'adk_submission', 'adk_eval_core')

def _wheel_is_compatible(path: Path) -> bool:
    try:
        from packaging.tags import sys_tags
        from packaging.utils import parse_wheel_filename
    except Exception:  # noqa: BLE001
        return True
    try:
        _, _, _, tags = parse_wheel_filename(path.name)
    except Exception:  # noqa: BLE001
        return True
    supported = set(sys_tags())
    return any(t in supported for t in tags)

all_wheels = sorted(tmp_whl.glob('*.whl'))
usable = [w for w in all_wheels if _wheel_is_compatible(w)]
skipped = [w.name for w in all_wheels if w not in usable]
T_INSTALL = time.time()
proc = subprocess.run([sys.executable, '-m', 'pip', 'install', '-q', '--no-deps', '--force-reinstall',
                       *(str(w) for w in usable)], capture_output=True, text=True)
if proc.returncode != 0:
    print('bulk install failed; retrying wheel-by-wheel to isolate the bad ones')
    failed = []
    for w in usable:
        r = subprocess.run([sys.executable, '-m', 'pip', 'install', '-q', '--no-deps', '--force-reinstall', str(w)],
                           capture_output=True, text=True)
        if r.returncode != 0:
            failed.append(w.name)
    skipped += failed
importlib.invalidate_caches()
print(f'wheelhouse: installed {len(all_wheels) - len(skipped)}/{len(all_wheels)} wheels in {time.time() - T_INSTALL:.0f}s '
      f'(python {sys.version_info.major}.{sys.version_info.minor})')
if skipped:
    print(f'  incompatible/failed ({len(skipped)}):', ', '.join(sorted(skipped)[:12]))
missing = []
for _pkg in REQUIRED_PKGS:
    try:
        importlib.import_module(_pkg)
    except Exception as _exc:  # noqa: BLE001
        missing.append(f'{_pkg} ({_exc.__class__.__name__}: {_exc})')
assert not missing, 'required packages unavailable: ' + '; '.join(missing)
print('  required packages present:', ', '.join(REQUIRED_PKGS))
print('no GPU required: this notebook never imports vllm/torch/litellm and loads no model.')

DATA_DIR = next(Path(p) for p in ['/kaggle/input/competitions/gemma-4-developer-agent',
                                  '/kaggle/input/gemma-4-developer-agent'] if Path(p).exists())
RUN_DIR = Path('/kaggle/working/runs') / EXP_ID
RUN_DIR.mkdir(parents=True, exist_ok=True)
print('data:', DATA_DIR, ' run dir:', RUN_DIR)

# %%
# ---------------------------------------------------------------- unpack embedded tool + shims + patches
TOOLS_DIR = Path('/kaggle/working/tools')
(TOOLS_DIR / 'compat_shims' / 'inline_snapshot').mkdir(parents=True, exist_ok=True)
(TOOLS_DIR / 'compat_shims' / 'dirty_equals').mkdir(parents=True, exist_ok=True)
(TOOLS_DIR / 'regrade_patches.py').write_bytes(base64.b64decode(REGRADE_SCRIPT_B64))
(TOOLS_DIR / 'compat_shims' / 'inline_snapshot' / '__init__.py').write_bytes(base64.b64decode(SHIM_INLINE_B64))
(TOOLS_DIR / 'compat_shims' / 'dirty_equals' / '__init__.py').write_bytes(base64.b64decode(SHIM_DIRTY_B64))

PATCHES_E0 = Path('/kaggle/working/patches_e0')
PATCHES_EXP003 = Path('/kaggle/working/patches_exp003')
for d, b64 in ((PATCHES_E0, E0_PATCHES_ZIP_B64), (PATCHES_EXP003, EXP003_PATCHES_ZIP_B64)):
    d.mkdir(parents=True, exist_ok=True)
    zipfile.ZipFile(io.BytesIO(base64.b64decode(b64))).extractall(d)
print('E0 patches:', len(list(PATCHES_E0.glob('*.patch'))), ' EXP-003 patches:', len(list(PATCHES_EXP003.glob('*.patch'))))

# %%
# ---------------------------------------------------------------- regrade both runs (subprocess sandbox, no GPU)
TASK_IDS_ARG = ','.join(TASK_IDS)

def run_regrade(label: str, patches_dir: Path, out_dir: Path) -> int:
    out_dir.mkdir(parents=True, exist_ok=True)
    cmd = [sys.executable, str(TOOLS_DIR / 'regrade_patches.py'),
           '--tasks', str(DATA_DIR / 'tasks.jsonl'),
           '--snapshots', str(DATA_DIR / 'snapshots'),
           '--wheels', str(DATA_DIR / 'wheels'),
           '--patches-dir', str(patches_dir),
           '--out', str(out_dir),
           '--label', label,
           '--task-ids', TASK_IDS_ARG]
    print('+', ' '.join(cmd))
    proc = subprocess.run(cmd, cwd='/kaggle/working')
    return proc.returncode

rc_e0 = run_regrade('E0', PATCHES_E0, RUN_DIR / 'E0')
rc_exp003 = run_regrade('EXP-003', PATCHES_EXP003, RUN_DIR / 'EXP-003')
print('exit codes:', {'E0': rc_e0, 'EXP-003': rc_exp003})

# %%
# ---------------------------------------------------------------- summary (full before/after comparison is done
# ---------------------------------------------------------------- locally against the original task_results.jsonl)
def load_jsonl(p: Path) -> list[dict]:
    if not p.exists():
        return []
    return [json.loads(line) for line in p.read_text(encoding='utf-8').splitlines() if line.strip()]

e0_rows = load_jsonl(RUN_DIR / 'E0' / 'regrade.jsonl')
exp003_rows = load_jsonl(RUN_DIR / 'EXP-003' / 'regrade.jsonl')
summary = {
    'exp_id': EXP_ID,
    'E0': {'n': len(e0_rows), 'resolved': sum(r['resolved'] for r in e0_rows)},
    'EXP-003': {'n': len(exp003_rows), 'resolved': sum(r['resolved'] for r in exp003_rows)},
}
(RUN_DIR / 'summary.json').write_text(json.dumps(summary, indent=1))
print(json.dumps(summary, indent=1))

# %%
# ---------------------------------------------------------------- bundle for download
shutil.make_archive(str(Path('/kaggle/working/runs') / EXP_ID), 'zip', RUN_DIR)
print('bundle:', Path('/kaggle/working/runs') / f'{EXP_ID}.zip')
